mapper.select:
SELECT 
  idx,
  chatSeq,
  input,
  output 
FROM
  DOGPOO_AI_CHATBOT_HISTORY 
WHERE userId = #{userId} AND mode = #{mode}
  AND LENGTH(output) > 0 
  AND (
    chatSeq > ${startSeq} 
    AND chatSeq <= ${lastSeq}
  )

SELECT 
  CONCAT(
    IFNULL((SELECT CONCAT('0. ', content, '\n') FROM DOGPOO_AI_CHATBOT_LONGTERM WHERE userId = #{userId} AND mode = #{mode} ORDER BY idx DESC LIMIT 1), ''),
    GROUP_CONCAT(CONCAT(number, '. ', content) SEPARATOR '\n')
  ) AS content
FROM
  (SELECT row_number() over ( ORDER BY idx ) AS number, content FROM DOGPOO_AI_CHATBOT_SUMMARY
  WHERE userId = #{userId}
  AND mode = #{mode}
  AND (
    summarySeq > ${startSeq}
    AND summarySeq <= ${lastSeq}
  )
) AS a
